#include "HostProviderTestSupport.hpp"
namespace {
struct Audit {std::atomic<int> calls{0},deaths{0},late{0};std::atomic<bool> alive{true};std::vector<std::uint8_t> bytes;};
struct AuditedReceiver final:InputChannels::Receiver {
    std::shared_ptr<Audit> audit;std::function<void()> pause;explicit AuditedReceiver(std::shared_ptr<Audit> a):audit(std::move(a)){audit->alive=true;}
    ~AuditedReceiver(){audit->alive=false;++audit->deaths;}
    void OnDataReceived(const rtps::octet*p,std::uint32_t n,const Locator&,const Locator&)override{if(!audit->alive)++audit->late;++audit->calls;if(pause)pause();audit->bytes.assign(p,p+n);}
};
struct Observer final:ProcessReceiveObserver {
    Event entered,release;bool pause_capture=false;std::atomic<bool> paused{false};
    void OnReceive(ReceiveStage stage,const ReceiveDiagnostic&,const std::uint8_t*,std::size_t)noexcept override {
        if(stage==ReceiveStage::Captured&&pause_capture&&!paused.exchange(true)){entered.Signal();try{release.Wait();}catch(...){std::abort();}}
    }
};
struct C {
    DSoftBusTransportDescriptor config=Config();std::shared_ptr<Mock> mock=std::make_shared<Mock>();
    std::shared_ptr<Observer> observer=std::make_shared<Observer>();
    std::shared_ptr<HostProviderLoop> loop=std::make_shared<HostProviderLoop>(mock,observer);
    std::unique_ptr<DSoftBusTransport> transport=HostFacadeTestAccess::Create(config,loop);
    rtps::SendResourceList senders;
    C(){Check(transport->init(),"init");Check(transport->OpenOutputChannel(senders,L(3)),"sender");}
    bool Open(InputChannels::Receiver* p){return transport->OpenInputChannel(L(2),p,64);}
    bool Close(){return transport->CloseInputChannel(L(2));}
    void Emit(std::uint8_t value=7){mock->callbacks.OnBytes(42,&value,1);}
    bool Send(){std::uint8_t b=19;std::vector<rtps::NetworkBuffer> buffers{{&b,1}};std::vector<Locator> peers{L(3)};rtps::Locators begin(peers.begin()),end(peers.end());return senders.front()->send(buffers,1,&begin,&end,std::chrono::steady_clock::now()+5s,0);}
    void Delivered(){Check(loop->PumpReceive()==BackendStatus::None,"delivery");}
    void Shutdown(){transport->shutdown();auto v=loop->Observe();Check(v.closed&&v.active_pumps==0&&v.tx.records==0&&v.tx.bytes==0,"whole work settled");}
};
void Basic(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Check(c.Open(r.get()),"open R1");c.Emit();c.Delivered();const auto old=c.loop->Observe().adapter.binding.receiver_identity;const auto native=c.loop->Observe().adapter.binding.owner_incarnation;Check(c.Close(),"independent close must succeed");r.reset();Check(a->deaths==1&&!c.transport->IsInputChannelOpen(L(2)),"R1 may die");auto b=std::make_shared<Audit>();auto r2=std::make_unique<AuditedReceiver>(b);Check(c.Open(r2.get()),"same local reopen");const auto now=c.loop->Observe().adapter.binding.receiver_identity;Check(old.application_incarnation&&!(old==now),"real receiver identity renewed");Check(c.mock->creates==1&&c.mock->closes==0&&c.loop->Observe().adapter.binding.owner_incarnation==native,"TX/native retained");c.Emit(8);c.Delivered();Check(b->calls==1&&a->calls==1,"only R2");Check(c.Close(),"close R2");r2.reset();c.Shutdown();}
void Destroy(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Check(c.Open(r.get()),"open");const bool result=c.Close();r.reset();Check(result,"caller ignores bool for receiver lifetime");c.Emit();Check(c.loop->PumpReceive()!=BackendStatus::None&&a->calls==0&&a->late==0&&a->deaths==1,"no access after return");c.Shutdown();}
void QueuedRx(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Check(c.Open(r.get()),"open");c.Emit();Check(c.loop->Observe().receive.queued==1,"actually queued");Check(c.Close(),"queued closes without pump");r.reset();auto usage=c.loop->Observe().receive;Check(usage.queued==0&&usage.bytes==0&&usage.copying==0&&a->calls==0,"queue canceled/bytes refunded");c.Shutdown();}
void Copy(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Check(c.Open(r.get()),"open");c.observer->pause_capture=true;std::thread ingress,close;std::atomic<bool> done=false;bool result=false;Cleanup guard{[&]{c.observer->release.Signal();if(ingress.joinable())ingress.join();if(close.joinable())close.join();}};ingress=std::thread([&]{c.Emit();});c.observer->entered.Wait();Check(c.loop->Observe().receive.copying>0,"actual captured copy charged");close=std::thread([&]{result=c.Close();done=true;});Check(c.loop->WaitInputClosing(std::chrono::steady_clock::now()+3s),"close seal observed");Check(!done&&!c.transport->IsInputChannelOpen(L(2)),"close waits copy");c.observer->release.Signal();ingress.join();close.join();Check(result,"copy settled close");r.reset();Check(c.loop->Observe().receive.bytes==0,"copy bytes settled");c.Shutdown();}
void Running(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Event entered,release;r->pause=[&]{entered.Signal();release.Wait();};Check(c.Open(r.get()),"open");c.Emit();std::thread pump,close;std::atomic<bool> done=false;bool result=false;Cleanup guard{[&]{release.Signal();if(pump.joinable())pump.join();if(close.joinable())close.join();}};pump=std::thread([&]{c.loop->PumpReceive();});entered.Wait();close=std::thread([&]{result=c.Close();done=true;});Check(c.loop->WaitInputClosing(std::chrono::steady_clock::now()+3s),"close began");Check(!done,"receiver drain not premature");release.Signal();pump.join();close.join();Check(result,"running close");r.reset();c.Emit();Check(c.loop->PumpReceive()!=BackendStatus::None&&a->calls==1&&a->late==0,"old receiver retired");c.Shutdown();}
void Sending(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Check(c.Open(r.get())&&c.Send(),"open/send");Event entered,release;c.mock->during_send=[&]{entered.Signal();release.Wait();};std::thread send;NativeSendRunResult result;Cleanup guard{[&]{release.Signal();if(send.joinable())send.join();}};send=std::thread([&]{result=c.loop->PumpSend();});entered.Wait();Check(c.Close(),"RX close independent of paused TX");r.reset();Check(c.mock->closes==0&&c.loop->Observe().tx.bytes>0,"owner/payload pinned");release.Signal();send.join();Check(result.status==NativeStatus::None&&c.mock->sends==1&&a->calls==0,"send completes, gap echo dropped");Check(c.Send(),"retained sender still valid");c.loop->PumpSend();c.Shutdown();Check(c.mock->closes==1,"one final native close");}
void Gap(){C c;auto a=std::make_shared<Audit>();auto r=std::make_unique<AuditedReceiver>(a);Check(c.Open(r.get()),"open");c.Emit(1);Check(c.Close(),"close cancels old record");r.reset();c.Emit(2);Check(c.loop->Observe().receive.bytes==0,"gap terminal no copy");auto b=std::make_shared<Audit>();AuditedReceiver r2(b);Check(c.Open(&r2),"reopen");Check(c.loop->PumpReceive()!=BackendStatus::None&&b->calls==0,"no old or gap adoption");c.Emit(3);c.Delivered();Check(b->bytes==std::vector<std::uint8_t>{3},"new legitimate callback delivered");Check(c.Close(),"close");c.Shutdown();}
void SameAddress(){C c;alignas(AuditedReceiver) unsigned char storage[sizeof(AuditedReceiver)];auto a=std::make_shared<Audit>();auto* r=new(storage)AuditedReceiver(a);Cleanup destroy{[&]{if(r){c.Close();r->~AuditedReceiver();}}};Check(c.Open(r),"open R1");c.Emit(1);const auto id=c.loop->Observe().adapter.binding.receiver_identity;Check(c.Close(),"close before placement reuse");r->~AuditedReceiver();r=nullptr;auto b=std::make_shared<Audit>();r=new(storage)AuditedReceiver(b);Check(c.Open(r),"same address R2");Check(!(id==c.loop->Observe().adapter.binding.receiver_identity),"address not identity");Check(c.loop->PumpReceive()!=BackendStatus::None,"old queued record never retargeted");c.Emit(2);c.Delivered();Check(a->calls==0&&b->calls==1,"only new ownership");Check(c.Close(),"close R2");r->~AuditedReceiver();r=nullptr;c.Shutdown();}
void ReopenFailure(){C c;auto a=std::make_shared<Audit>();AuditedReceiver r1(a);Check(c.Open(&r1)&&c.Close(),"initial close");auto b=std::make_shared<Audit>();AuditedReceiver r2(b);auto local=L(2);loop_deny_allocations=true;bool opened=false;try{opened=c.transport->OpenInputChannel(local,&r2,64);}catch(...){loop_deny_allocations=false;throw;}loop_deny_allocations=false;Check(!opened&&!c.transport->IsInputChannelOpen(local),"allocation rollback");Check(c.loop->Observe().receive.active_applications==0,"no orphan claim");Check(c.Open(&r2),"same object same local retry");c.Emit();c.Delivered();Check(b->calls==1&&c.mock->creates==1,"reopen no native create");Check(c.Close(),"close");c.Shutdown();}
void Locators(){C c;Check(!c.transport->IsInputChannelOpen(L(2))&&c.Close(),"initial idempotent close");auto a=std::make_shared<Audit>();AuditedReceiver r(a),other(std::make_shared<Audit>());Check(c.Open(&r)&&c.Open(&r),"same receiver idempotent");Check(!c.Open(&other),"different receiver refused");Locator bad=L(2);bad.kind=1;Check(!c.transport->CloseInputChannel(L(9))&&!c.transport->CloseInputChannel(bad)&&c.transport->IsInputChannelOpen(L(2)),"wrong locators no effect");Check(c.transport->DoInputLocatorsMatch(L(2),L(2))&&!c.transport->DoInputLocatorsMatch(L(2),L(3)),"exact mapping");Check(c.Close()&&c.Close()&&c.mock->closes==0,"local no double native close");c.Shutdown();Check(c.Close()&&c.mock->closes==1&&!c.Open(&r),"after whole shutdown no revival");}
void Fault(){C c;auto a=std::make_shared<Audit>();AuditedReceiver r(a);r.pause=[] {throw std::runtime_error("receiver");};Check(c.Open(&r),"open");c.Emit();Check(c.loop->PumpReceive()==BackendStatus::CallbackFailure,"receiver exception");c.mock->callbacks.OnShutdown(42);Check(c.Close(),"provider stop still drains RX");AuditedReceiver r2(std::make_shared<Audit>());Check(!c.Open(&r2),"stopped provider cannot revive");c.mock->throw_close=true;c.transport->shutdown();auto status=c.loop->Observe().close.status;c.transport->shutdown();Check(status==BackendStatus::ProviderException&&c.loop->Observe().close.status==status&&c.mock->closes==1,"failure preserved");}
void AllocationSweep(){C c;auto a=std::make_shared<Audit>();AuditedReceiver r(a);Check(c.Open(&r)&&c.Close(),"initial close");int failures=0,successes=0;for(long n=0;n<40;++n){loop_fail_after=n;bool opened=c.Open(&r);loop_fail_after=-1;if(!opened){++failures;auto u=c.loop->Observe().receive;Check(!c.transport->IsInputChannelOpen(L(2))&&u.active_applications==0&&u.retained_applications==0&&u.bytes==0,"failed reopen leaves no claim/lease/bytes");Check(c.Open(&r),"same object retry after every allocation failure");}else ++successes;Check(c.Close(),"close sweep generation");}Check(failures>4&&successes>0&&c.mock->creates==1,"multiple registration allocation stages covered");c.Shutdown();}
void CallbackDuringClose(){
    C c;auto a=std::make_shared<Audit>();AuditedReceiver r(a);Event entered,try_close;bool refused=false;
    r.pause=[&]{entered.Signal();try_close.Wait();std::cerr<<"RECEIVER_REENTRANT_CLOSE\n"<<std::flush;refused=!c.Close();};
    Check(c.Open(&r),"open");c.Emit();std::thread pump,close;bool result=false;
    Cleanup guard{[&]{try_close.Signal();if(pump.joinable())pump.join();if(close.joinable())close.join();}};
    pump=std::thread([&]{c.loop->PumpReceive();});entered.Wait();close=std::thread([&]{result=c.Close();});
    Check(c.loop->WaitInputClosing(std::chrono::steady_clock::now()+3s),"external close holds control and drains");
    std::cerr<<"EXTERNAL_CLOSE_DRAINING\n"<<std::flush;try_close.Signal();pump.join();close.join();
    Check(refused&&result&&!c.transport->IsInputChannelOpen(L(2)),"callback refusal before control lock; external close completes");c.Shutdown();
}
void CallbackControl(){C c;auto a=std::make_shared<Audit>();AuditedReceiver r(a);bool refused=false;r.pause=[&]{refused=!c.Close();};Check(c.Open(&r),"open");c.Emit();c.Delivered();Check(refused&&c.transport->IsInputChannelOpen(L(2)),"forbidden callback close rejects without changing channel");Check(c.Close(),"legal external close");c.Shutdown();}
}
int main(int argc,char**argv){try{Check(argc==2,"case required");std::string name=argv[1];const std::pair<const char*,void(*)()> cases[]={{"basic",Basic},{"destroy",Destroy},{"queued",QueuedRx},{"copy",Copy},{"running",Running},{"sending",Sending},{"gap",Gap},{"same-address",SameAddress},{"reopen-failure",ReopenFailure},{"locators",Locators},{"fault",Fault},{"allocation-sweep",AllocationSweep},{"callback-control",CallbackControl},{"callback-during-close",CallbackDuringClose}};for(auto c:cases)if(name==c.first){c.second();std::cout<<"PASS "<<name<<'\n';return 0;}throw std::runtime_error("unknown case");}catch(const std::exception&e){loop_deny_allocations=false;loop_fail_after=-1;std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
